import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Hub meta-tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/hub-tools.md","filePath":"reference/hub-tools.md","lastUpdated":1787179449000}`),a={name:`reference/hub-tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="hub-meta-tools" tabindex="-1">Hub meta-tools <a class="header-anchor" href="#hub-meta-tools" aria-label="Permalink to “Hub meta-tools”">​</a></h1><p>The <code>/hub</code> endpoint exposes exactly six tools, regardless of how many servers are configured. Four of them are how a client reaches everything else; the remaining two (<code>wake_server</code>, <code>sleep_server</code>) steer the <a href="/guide/on-demand">on-demand lifecycle</a>.</p><p>Servers marked <a href="/guide/configuration#hiding-a-server-from-hub"><code>&quot;hub&quot;: false</code></a> keep their <em>tools</em> out of the aggregate: <code>list_tools</code>, <code>get_tool_schema</code> and <code>call_tool</code> refuse them with a pointer to the server&#39;s own endpoint. Their <em>lifecycle</em> is still the hub&#39;s business — <code>list_servers</code> shows them with a <code>hidden</code> marker, and <code>wake_server</code>/<code>sleep_server</code> manage them like any other on-demand server.</p><p>The <a href="/guide/clients#local-clients-over-stdio">stdio mode</a> serves the same six tools with the same behaviour — everything on this page applies there too.</p><h2 id="the-intended-sequence" tabindex="-1">The intended sequence <a class="header-anchor" href="#the-intended-sequence" aria-label="Permalink to “The intended sequence”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>list_servers  →  list_tools(server)  →  get_tool_schema(server, tool)  →  call_tool(...)</span></span></code></pre></div><p>A model that already knows a tool&#39;s schema can skip straight to <code>call_tool</code>. The tool descriptions are written to steer that order, so no client-side prompting is needed.</p><h2 id="list-servers" tabindex="-1"><code>list_servers</code> <a class="header-anchor" href="#list-servers" aria-label="Permalink to “list_servers”">​</a></h2><blockquote><p>List all MCP servers available through this hub, with their status. Call this first to see what is available.</p></blockquote><p>No input.</p><p>Returns one entry per hub-enabled server:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">[</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;name&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;paperless&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;description&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;Paperless-ngx&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;status&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;up&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,       </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;toolCount&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">14</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> },</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;name&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;calendar&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,  </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;description&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;CalDAV&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,        </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;status&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;sleeping&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;toolCount&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">6</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;hidden&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">true</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">]</span></span></code></pre></div><p><code>description</code> is the child&#39;s advertised title, falling back to its server name. <code>status</code> is <code>starting</code>, <code>up</code>, <code>down</code> or <code>sleeping</code>. Listing never wakes anything — <code>sleeping</code> entries still show their cached <code>toolCount</code>. <code>hidden</code> appears only on <code>&quot;hub&quot;: false</code> servers: their tools are served exclusively by their own endpoint, but <code>wake_server</code>/<code>sleep_server</code> accept them.</p><h2 id="list-tools" tabindex="-1"><code>list_tools</code> <a class="header-anchor" href="#list-tools" aria-label="Permalink to “list_tools”">​</a></h2><blockquote><p>List the tools of one MCP server with one-line descriptions. Use <code>get_tool_schema</code> before calling a tool for the first time.</p></blockquote><table tabindex="0"><thead><tr><th>Input</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>server</code></td><td>string, required</td><td>server name from <code>list_servers</code></td></tr></tbody></table><p>Returns names with one-line descriptions — the first line of each tool&#39;s description, truncated at 120 characters — so listing a large server stays cheap:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">[</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;name&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;search_documents&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;description&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;Full-text search across all documents&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> },</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;name&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;get_document&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,     </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;description&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;Fetch one document by ID&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">]</span></span></code></pre></div><p>Errors: an unknown server, or an always-running server that is not <code>up</code>, returns a tool error naming the state. A <code>sleeping</code> server answers from its cached snapshot and is <a href="/guide/on-demand#what-wakes-a-server-and-what-does-not">pre-warmed in the background</a> — asking for its tools is the strongest hint a call follows.</p><h2 id="get-tool-schema" tabindex="-1"><code>get_tool_schema</code> <a class="header-anchor" href="#get-tool-schema" aria-label="Permalink to “get_tool_schema”">​</a></h2><blockquote><p>Get the full description and JSON input schema of one tool, needed to construct arguments for <code>call_tool</code>.</p></blockquote><table tabindex="0"><thead><tr><th>Input</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>server</code></td><td>string, required</td><td>server name from <code>list_servers</code></td></tr><tr><td><code>tool</code></td><td>string, required</td><td>tool name from <code>list_tools</code></td></tr></tbody></table><p>Returns the untruncated description and the tool&#39;s JSON Schema:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;name&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;search_documents&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;description&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;Full-text search across all documents…&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;inputSchema&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;type&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;object&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;properties&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;query&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;type&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;string&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> } }, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;required&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;query&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">] }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">}</span></span></code></pre></div><p>This is the step that keeps context small: full schemas are pulled in one at a time, only for tools actually being used.</p><h2 id="call-tool" tabindex="-1"><code>call_tool</code> <a class="header-anchor" href="#call-tool" aria-label="Permalink to “call_tool”">​</a></h2><blockquote><p>Call a tool on one of the MCP servers. Arguments must match the schema from <code>get_tool_schema</code>.</p></blockquote><table tabindex="0"><thead><tr><th>Input</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>server</code></td><td>string, required</td><td>server name from <code>list_servers</code></td></tr><tr><td><code>tool</code></td><td>string, required</td><td>tool name from <code>list_tools</code></td></tr><tr><td><code>arguments</code></td><td>object, optional</td><td>arguments matching the tool&#39;s input schema</td></tr></tbody></table><p>The child&#39;s result is returned unchanged — content blocks, images, structured content and <code>isError</code> all pass through.</p><p>Timeout: 5 minutes, reset whenever the child sends a progress notification. A failure comes back as a tool error (<code>Tool call failed: …</code>) rather than an HTTP error, so the model can react to it.</p><p>Calling a <code>sleeping</code> server wakes it first and blocks until it is up (120-second budget) — the call itself then proceeds normally. Only a start that fails for the whole budget surfaces as a tool error.</p><h2 id="wake-server" tabindex="-1"><code>wake_server</code> <a class="header-anchor" href="#wake-server" aria-label="Permalink to “wake_server”">​</a></h2><blockquote><p>Start an on-demand server now so its first tool call is fast. No-op if it is already running.</p></blockquote><table tabindex="0"><thead><tr><th>Input</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>server</code></td><td>string, required</td><td>server name from <code>list_servers</code></td></tr></tbody></table><p>Blocks until the server is up and returns <code>{ name, status, toolCount }</code>. Useful at the start of a longer workflow: the cold start happens while the model is still planning instead of inside the first real call. An always-running server (<code>keepAlive</code> or remote/socket) is refused with <code>… is always running</code>.</p><h2 id="sleep-server" tabindex="-1"><code>sleep_server</code> <a class="header-anchor" href="#sleep-server" aria-label="Permalink to “sleep_server”">​</a></h2><blockquote><p>Stop an on-demand server immediately instead of waiting for its idle timeout. It restarts automatically on the next tool call.</p></blockquote><table tabindex="0"><thead><tr><th>Input</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>server</code></td><td>string, required</td><td>server name from <code>list_servers</code></td></tr></tbody></table><p>Frees the server&#39;s resources right away — the stdio child exits, a sandbox container is removed. Returns <code>{ name, status }</code>; already-sleeping servers are a no-op. Always-running servers are refused.</p><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to “Caching”">​</a></h2><p>The hub keeps each child&#39;s tool list in memory and refreshes it when the child sends <code>tools/list_changed</code>. <code>list_servers</code> and <code>list_tools</code> are therefore answered without a round trip to the child. For on-demand servers the same snapshot is <a href="/guide/on-demand#the-tool-cache">persisted to disk</a>, which is what lets a sleeping server answer at all.</p><p>Clients are not notified of those changes — the <a href="/guide/architecture#stateless-transport">stateless transport</a> has no channel for server-initiated messages — but the next <code>list_tools</code> call reflects them.</p><h2 id="when-to-use-direct-paths-instead" tabindex="-1">When to use direct paths instead <a class="header-anchor" href="#when-to-use-direct-paths-instead" aria-label="Permalink to “When to use direct paths instead”">​</a></h2><p><code>/hub</code> trades one extra round trip for a much smaller context. For a server you call constantly, registering <code>/&lt;name&gt;/mcp</code> as its own connector puts the native tools directly in the model&#39;s hands. The two mix well: give the daily drivers their own connectors, mark them <code>&quot;hub&quot;: false</code>, and let <code>/hub</code> cover the long tail.</p>`,44)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};